//! `kat-derived-uuid-001` (proposal agentidentitytrustprotocol#72 Item
//! 6b), generated by `scripts/gen-proposal-kats.py` with Python hashlib.

use aitp_core::ids::{derived_v4, derived_v4_preimage, parse_v4};
use serde_json::Value;
use sha2::{Digest, Sha256};

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

#[test]
fn kat_derived_uuid_001() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/proposal-kats/p256-pinned-key-2026-10.json"
    );
    let doc: Value = serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();
    let v = doc["vectors"]
        .as_array()
        .unwrap()
        .iter()
        .find(|v| v["id"] == "kat-derived-uuid-001")
        .expect("vector present");
    let tag = v["domain_tag"].as_str().unwrap();
    let input = unhex(v["input_hex"].as_str().unwrap());

    let pre = derived_v4_preimage(tag, &input).unwrap();
    assert_eq!(pre, unhex(v["preimage_hex"].as_str().unwrap()));
    assert_eq!(
        Sha256::digest(&pre).as_slice(),
        unhex(v["sha256_hex"].as_str().unwrap())
    );
    let id = derived_v4(tag, &input).unwrap();
    assert_eq!(id.hyphenated().to_string(), v["uuid"].as_str().unwrap());
    assert_eq!(parse_v4(v["uuid"].as_str().unwrap()).unwrap(), id);
}
